const email=sessionStorage.getItem('uniify-pending-email'),status=document.querySelector('#flow-status');document.querySelector('#verification-recipient').textContent=email?'Enter the code sent to '+email+'.':'Create an account to request a verification code.';document.querySelector('#flow-form button').disabled=!email;document.querySelector('#resend-code').disabled=!email;
async function request(action,data){const response=await fetch('/api/auth/'+action,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(data)});if(!response.headers.get('content-type')?.includes('application/json'))throw Error('Email verification is not connected yet.');const result=await response.json();if(!response.ok)throw Error(result.error||'Verification failed. Check your code and try again.');return result}
document.querySelector('#flow-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await request('verify-email',{email,code:e.target.elements.code.value});sessionStorage.removeItem('uniify-pending-email');location.href='onboarding.html'}catch(error){status.textContent=error.message}finally{button.disabled=false}};
document.querySelector('#resend-code').onclick=async e=>{e.target.disabled=true;try{await request('resend-code',{email});status.textContent='A new code has been sent. You can resend again in 60 seconds.';setTimeout(()=>e.target.disabled=false,60000)}catch(error){status.textContent=error.message;e.target.disabled=false}};
